                                namespaceId: string | null;
                                namespaceName: string | null;
                                key: string;
                                sourceText: string;
                                translatedText: string | null;
                                sourceProjectLanguageId: string;
                                targetProjectLanguageId: string;
                                status: string;
                                currentSource: string | null;
                                metadata: unknown;
